flatten.example:
// client
const { Vector3 } = kcds.math;

const pad = kcds.world.Terrain.flatten(new Vector3(120, 200, 0), 7, 14.5, 6);
kcds.world.Prefab.place('house_1s_4r_angled_a_dobesovicko', new Vector3(120, 200, 14.5));

flatten.exampleCs:
// client

var pad = Terrain.Flatten(new Vector3(120, 200, 0), 7, 14.5, 6);
Prefab.Place("house_1s_4r_angled_a_dobesovicko", new Vector3(120, 200, 14.5));

raise.example:
// client
const { Vector3 } = kcds.math;

const hill = kcds.world.Terrain.raise(new Vector3(120, 200, 0), 3, 4, 6);
hill.undo();

raise.exampleCs:
// client

var hill = Terrain.Raise(new Vector3(120, 200, 0), 3, 4, 6);
hill.Call("undo");

paint.example:
// client: a cobbled lane through a meadow
const { Vector3 } = kcds.math;
const { Terrain } = kcds.world;

for (let x = 100; x <= 140; x += 2) {
  Terrain.paint(new Vector3(x, 200, 0), 1.5, 'cobblestones', 1);
}

paint.exampleCs:
// client: a cobbled lane through a meadow

for (var x = 100; x <= 140; x += 2)
{
    Terrain.Paint(new Vector3(x, 200, 0), 1.5, "cobblestones", 1);
}

materials.exampleCs:
// client
var names = Terrain.Materials().Keys;
Log.Info($"Ground materials: {string.Join(", ", names)}");

edits.example:
// client
for (const edit of kcds.world.Terrain.edits().reverse()) {
  edit.undo();
}

edits.exampleCs:
// client
foreach (var edit in Terrain.Edits().Call("reverse"))
{
    edit.Call("undo");
}
